# Edition 2, batch 1: items that fill the gaps in rarity and type.
# (name, category, rarity, attunement, text)
A = "Requires Attunement"
AS = "Requires Attunement by a Spellcaster"
ITEMS = [
# ================= RODS =================
("Surveyor's Rod", "Rod", "Uncommon", None, "This brass rod extends to a 10-foot pole or folds down to 1 foot as a Bonus Action. Notches along its length let you measure any distance you can see within 300 feet to the nearest foot. Once per Long Rest, you can tap the rod on a floor or wall as a Magic action. You learn whether a hollow space, a pit, or a pressure plate lies within 10 feet of that point, but not where it is."),
("Rod of the Lodestar", "Rod", "Uncommon", A, "While you hold this iron rod, you can take a Magic action to pull an unattended metal object of up to 20 pounds within 60 feet to your free hand. In addition, when a creature you can see within 30 feet makes an attack roll with a metal weapon, you can take a Reaction to give that roll Disadvantage. You can use this Reaction twice, and you regain all uses at dawn."),
("Rod of Quiet Halls", "Rod", "Rare", A, "This rod has 3 charges and regains 1d3 expended charges daily at dawn. While holding it, you can take a Magic action to expend 1 charge and cast Silence from it. The spell doesn't require Concentration and lasts 10 minutes. Alternatively, you can expend 1 charge to cast Arcane Lock on a door or chest you touch with the rod."),
("Rod of the Iron Verdict", "Rod", "Very Rare", A, "While you hold this black iron rod, you have Advantage on Wisdom (Insight) checks to tell whether a creature is lying. As a Magic action, you can point the rod at a creature you can see within 60 feet and cast Hold Monster (save DC 17) on it without expending a spell slot. Once you use this property, it can't be used again until the next dawn."),
("Rod of the Long Night", "Rod", "Very Rare", A, "While holding this rod, you have Darkvision with a range of 120 feet, and you can see through magical Darkness out to that range. The rod has 5 charges and regains 1d4 + 1 expended charges daily at dawn. You can expend charges to cast one of the following spells from it (save DC 17): Darkness (2 charges), Blindness/Deafness at level 3 (3 charges), or Eyebite (5 charges)."),
# ================= SCROLLS =================
("Paper Sparrow Letter", "Scroll", "Common", None, "Write a message of up to twenty-five words on this sheet, then speak the name of a creature you have met. The sheet folds itself into a paper sparrow and flies at a Speed of 60 feet to that creature, if it is within 5 miles, and unfolds in its hands. If the creature is farther away, the sparrow lands at your feet. Once delivered, the letter crumbles to ash after it is read."),
("Scroll of the Kept Promise", "Scroll", "Common", None, "Two creatures write a promise on this scroll and sign it. If either signer breaks the written promise, the ink of that signer's name turns red. The scroll can't be used again, but it lasts until it is destroyed."),
("Scroll of Second Sight", "Scroll", "Uncommon", None, "You can read this scroll as a Bonus Action. For 1 minute afterward, you can see Invisible creatures and objects within 30 feet of you, and you can see into the Ethereal Plane out to the same range. The scroll then turns to dust."),
("Scroll of the Way Back", "Scroll", "Rare", None, "As a Magic action, you read this scroll aloud. You and up to five willing creatures within 30 feet of you teleport to the spot where you last finished a Long Rest, if that spot is within 1 mile of you. If it is farther away, nothing happens and the scroll is not used up. Otherwise, the scroll turns to dust."),
# ================= AMMUNITION =================
("Whistling Arrow", "Ammunition", "Common", None, "In flight, this arrow lets out a shrill note that can be heard up to 1 mile away. You choose high, low, or warbling when you nock it, so your allies can agree on signals ahead of time. The arrow is not destroyed after it is fired. Found in bundles of 1d6 + 2."),
("Grappling Bolt", "Ammunition", "Uncommon", None, "When this bolt strikes a wall, a tree, or another solid surface within 100 feet, barbs lock it in place and a thin, strong cord spools out between the bolt and your crossbow. The cord holds up to 500 pounds and vanishes after 1 hour. If the bolt hits a Large or smaller creature instead, the creature makes a DC 13 Strength save or its Speed is 0 until it takes an action to pull the bolt free. Found in bundles of 1d4 + 1."),
("Arrow of the Burning Dawn", "Ammunition", "Rare", None, "On a hit, the target takes an extra 2d8 Radiant damage, or 4d8 if it is a Fiend or an Undead. Until the end of your next turn, it sheds Bright Light in a 10-foot radius and can't become Invisible. The arrow then burns away."),
("Avalanche Stone", "Ammunition", "Rare", None, "When you hit a creature with this sling bullet, it bursts into gravel. Each creature in a 10-foot-radius Sphere centered on the target makes a DC 15 Dexterity save. On a failed save, a creature takes 3d8 Bludgeoning damage and has the Prone condition. On a successful save, it takes half as much damage only. Found in bundles of 1d4."),
("Bolt of the Broken Ward", "Ammunition", "Very Rare", None, "On a hit, the target takes an extra 4d10 Force damage, and each spell of level 5 or lower that affects the target ends. The bolt then shatters."),
# ================= STAFFS =================
("Shepherd's Crook", "Staff", "Uncommon", A, "This hooked staff can be wielded as a Quarterstaff. Once on each of your turns, you can hook a willing Medium or smaller creature within 10 feet of you and pull it to an unoccupied space next to you (no action required). That movement doesn't provoke Opportunity Attacks. The staff has 3 charges and regains 1d3 expended charges daily at dawn. You can expend 1 charge to cast Sanctuary, or 2 charges to cast Calm Emotions (save DC 13)."),
("Staff of Seven Winds", "Staff", "Rare", AS, "This staff can be wielded as a Quarterstaff. While holding it, you can't be pushed or knocked Prone by wind, magical or otherwise. The staff has 7 charges and regains 1d6 + 1 expended charges daily at dawn. You can expend charges to cast one of the following spells from it (save DC 15): Feather Fall (1 charge), Gust of Wind (2 charges), or Wind Wall (3 charges)."),
("Staff of the Deep Root", "Staff", "Very Rare", "Requires Attunement by a Druid or Ranger", "This staff of living oak is a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls made with it. While holding it, you also gain a +2 bonus to spell attack rolls. The staff has 10 charges and regains 1d6 + 4 expended charges daily at dawn. You can expend charges to cast one of the following spells from it (save DC 17): Spike Growth (2 charges), Plant Growth (3 charges), Wall of Stone (5 charges), or Transport via Plants (6 charges). If you expend the last charge, roll 1d20. On a 1, the staff takes root where it stands and grows into an oak tree."),
# ================= WANDS =================
("Wand of Bright Bubbles", "Wand", "Common", None, "As a Magic action, you can wave this wand to release a stream of soap bubbles that drift for 1 minute. Each bubble sheds Dim Light in a 1-foot radius and pops with a tiny chime when it touches anything. Once per Long Rest, you can also use the wand to clean one object or creature you touch, as with Prestidigitation."),
("Wand of Frost Bindings", "Wand", "Uncommon", AS, "This wand has 7 charges and regains 1d6 + 1 expended charges daily at dawn. As a Magic action, you can expend 1 charge to target a creature you can see within 60 feet. The target makes a DC 13 Constitution save. On a failed save, it takes 2d6 Cold damage and its Speed is 0 until the start of your next turn. On a successful save, it takes half as much damage only. If you expend the last charge, roll 1d20. On a 1, the wand melts into cold water."),
("Wand of Unraveling", "Wand", "Very Rare", AS, "This wand has 7 charges and regains 1d6 + 1 expended charges daily at dawn. While holding it, you can expend 1 charge to cast Dispel Magic from it. For each additional charge you expend, the spell's level increases by 1, to a maximum of level 6. You can also expend 2 charges to cast Counterspell (save DC 17) from it."),
("Wand of the Falling Star", "Wand", "Legendary", AS, "This wand has 7 charges and regains 1d6 + 1 expended charges daily at dawn. While holding it, you can expend charges to cast one of the following spells from it (save DC 18, +10 to hit): Scorching Ray (1 charge), Wall of Fire (3 charges), or Meteor Swarm (7 charges)."),
# ================= RINGS =================
("Ring of the Borrowed Voice", "Ring", "Common", None, "Once per Long Rest, as a Bonus Action, you can make your voice sound like the voice of any creature you heard speak within the last 24 hours. The effect lasts for 10 minutes. A creature that knows the real voice well can tell the difference with a successful DC 13 Wisdom (Insight) check."),
("Ring of the Second Shadow", "Ring", "Rare", A, "Once per Long Rest, as a Magic action, you can send your shadow away from your body for up to 1 hour. The shadow is Invisible, moves 30 feet on each of your turns along floors, walls, and ceilings, and can slip through any gap that light passes through. You can see and hear through it as if you were there. It can't interact with anything and returns to you if you dismiss it, if it enters Bright Light, or if the duration ends."),
("Ring of the Unbowed", "Ring", "Very Rare", A, "While wearing this ring, you have Immunity to the Frightened condition and Resistance to Psychic damage. In addition, once per Long Rest, when you fail a saving throw to avoid or end the Charmed, Paralyzed, or Stunned condition, you can choose to succeed instead."),
("Ring of the Last Hour", "Ring", "Legendary", A, "While wearing this ring, you can't be aged by magic. When you drop to 0 Hit Points but don't die outright, you can turn the ring on your finger (no action required). Time folds back around you: you return to the space you were in at the start of your previous turn, with the Hit Points and conditions you had then. Expended spell slots and other resources stay expended. The ring can't be used again for 7 days."),
# ================= POTIONS =================
("Potion of the Iron Mountain", "Potion", "Very Rare", None, "For 1 hour after you drink this potion, you have Resistance to Bludgeoning, Piercing, and Slashing damage, and you can't be moved against your will or given the Prone condition. While the effect lasts, your Speed is reduced by 10 feet."),
("Potion of Starlit Wings", "Potion", "Very Rare", None, "For 1 hour after you drink this potion, you have a Fly Speed of 60 feet and can hover. Once before the effect ends, when you would take damage, you can take a Reaction to burst into starlight and teleport up to 60 feet to an unoccupied space you can see, taking no damage from the triggering effect."),
("Draught of the Sealed Mind", "Potion", "Legendary", None, "This potion tastes of nothing at all. For 24 hours after you drink it, you have Immunity to Psychic damage and the Charmed condition, and you are unaffected by anything that would read your thoughts, learn whether you are lying, or detect your emotions. Divination spells can't target you or perceive you, and you can't be found by Scrying sensors."),
# ================= WEAPONS =================
("Woodcutter's Handaxe", "Weapon (Handaxe)", "Common", None, "This handaxe never gets stuck in wood and splits a log with a single swing. When you throw it and miss, it lands at your feet instead of near the target."),
("Javelin of the Racing Hare", "Weapon (Javelin)", "Uncommon", None, "You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. If you move at least 20 feet in a straight line right before you throw it, it deals an extra 1d6 Piercing damage on a hit. After the attack, the javelin flies back to your hand."),
("Whip of the Beast Tamer", "Weapon (Whip)", "Uncommon", None, "You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. As a Bonus Action, you can crack the whip. Each Beast within 30 feet of you that can hear the crack makes a DC 13 Wisdom save or has the Frightened condition until the end of its next turn. You can crack the whip this way three times, and you regain all uses at dawn."),
("Scimitar of the Shifting Dune", "Weapon (Scimitar)", "Rare", A, "You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. When you hit a creature with it, you can whip up a spray of sand. The target makes a DC 15 Constitution save or has the Blinded condition until the start of your next turn. You can use this property three times, and you regain all uses at dawn. While carrying the scimitar, you ignore Difficult Terrain made of sand or loose earth."),
("Halberd of the Bridge Keeper", "Weapon (Halberd)", "Rare", A, "You gain a +2 bonus to attack rolls and damage rolls made with this magic weapon. While you hold it with two hands, you can't be pushed or pulled against your will, and other creatures treat the spaces within 5 feet of you as Difficult Terrain."),
("Crossbow of the Siege Line", "Weapon (Heavy Crossbow)", "Very Rare", A, "You gain a +2 bonus to attack rolls and damage rolls made with this magic weapon, and it deals double damage to objects and structures. Once per dawn, when you fire it, you can make the bolt burst on impact instead of making an attack roll. Choose a point within the weapon's normal range. Each creature in a 20-foot-radius Sphere centered there makes a DC 17 Dexterity save, taking 8d6 Thunder damage on a failed save or half as much on a successful one."),
("Glaive of the Waning Moon", "Weapon (Glaive)", "Very Rare", A, "You gain a +3 bonus to attack rolls and damage rolls made with this magic weapon. Its silver blade sheds Dim Light in a 5-foot radius, and while you hold it, you can see normally in magical and nonmagical Darkness within 60 feet."),
# ================= ARMOR =================
("Fisher's Oilskin", "Armor (Padded)", "Common", None, "Water beads off this padded armor, so it and the clothes under it never get wet. While you wear it, it holds you up in water, and you can float without effort."),
("Ring Mail of the Gate Guard", "Armor (Ring Mail)", "Uncommon", None, "You have a +1 bonus to AC while wearing this armor. While you wear it, you can't fall asleep against your will while you stand, and you have Advantage on saving throws to avoid or end the Unconscious condition caused by magical sleep."),
("Splint of the Bastion", "Armor (Splint)", "Rare", A, "You have a +1 bonus to AC while wearing this armor. When an ally within 5 feet of you is hit by an attack, you can take a Reaction to step into the blow: you become the target of the attack instead, and it hits you. You can use this Reaction a number of times equal to your Proficiency Bonus, and you regain all uses when you finish a Long Rest."),
("Shadowsilk Jerkin", "Armor (Leather)", "Very Rare", A, "You have a +2 bonus to AC while wearing this armor, and you have Resistance to Necrotic damage. Once per dawn, when you take damage, you can take a Reaction to step into a shadow. You teleport to an unoccupied space in Dim Light or Darkness within 30 feet of you, and you take only half the damage."),
("Oathplate of the Last Gate", "Armor (Plate)", "Legendary", A, "You have a +3 bonus to AC while wearing this armor, and you have Immunity to the Frightened condition. While you are Bloodied but have at least 1 Hit Point, you regain 5 Hit Points at the start of each of your turns. Once per dawn, when you drop to 0 Hit Points but don't die outright, you drop to 1 Hit Point instead."),
]
